﻿using Lecos.Strassennamen.Data.Interfaces;
using Lecos.Strassennamen.RestAPI.Authorization;
using Lecos.Strassennamen.RestAPI.DTOs;
using Lecos.Strassennamen.RestAPI.Extensions;
using Microsoft.AspNetCore.Authorization;
using Microsoft.AspNetCore.Mvc;

namespace Lecos.Strassennamen.RestAPI.Controllers;

[ApiController]
[Route("api/[controller]")]
[Authorize(ClientRoles.AppAccess)]
public class NamenskomplexController : ControllerBase
{
    private readonly INamenskomplexRepository repository;

    public NamenskomplexController(INamenskomplexRepository repository)
    {
        this.repository = repository;
    }

    [HttpGet]
    public async Task<ActionResult<IReadOnlyCollection<Namenskomplex>>> GetAll()
    {
        var result = await repository.GetAll();

        return Ok(result.Select(m => m.ToDTO()).ToList());
    }

    [HttpGet("{id}")]
    public async Task<ActionResult<Namenskomplex>> Get(long id)
    {
        var result = await repository.Get(id);

        return Ok(result?.ToDTO());
    }

    [HttpPost]
    [Authorize(ClientRoles.Editor)]
    public async Task<ActionResult<Namenskomplex>> Create([FromBody] Namenskomplex dto)
    {
        var result = await repository.Save(dto.ToModel());

        return Ok(result?.ToDTO());
    }

    [HttpPut]
    [Authorize(ClientRoles.Editor)]
    public async Task<ActionResult<Namenskomplex>> Update([FromBody] Namenskomplex dto)
    {
        var result = await repository.Save(dto.ToModel());

        return Ok(result?.ToDTO());
    }

    [HttpDelete("{id}")]
    [Authorize(ClientRoles.Editor)]
    public async Task<ActionResult<Namenskomplex>> DeleteSoft(long id)
    {
        var model = await repository.Get(id);
        if (model is not null)
        {
            model.IsDeleted = true;
            await repository.Save(model);
        }

        return Ok(model?.ToDTO());
    }
}
